import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import UserLogin from './Components/Authentication/JavaScript/UserLogin';
import GISSurveyorSignup from './Components/Authentication/JavaScript/SignUp';
import Map from './Components/MapAndForms/JavaScript/map';

import { AuthProvider, useAuth } from './Components/Authentication/JavaScript/AuthContext';
import ProtectedRoute from './Components/Authentication/JavaScript/ProtectedRoute';
impo
import FormSelectionModal from "./Components/MapAndForms/JavaScript/FormSelectionModal";
import PropertyDetailsForm from "./Components/MapAndForms/JavaScript/PropertyDetailsForm";

function AppRoutes() {
  const { authLoading } = useAuth();

  // ⛔ Prevent route rendering until auth is resolved
  if (authLoading) {
    return null; // or a loader
  }

  return (
    <Routes>
      <Route path="/" element={<UserLogin />} />
      <Route path="/signup" element={<GISSurveyorSignup />} />

      {/* 🔐 Protected Map Route */}
      <Route
        path="/map"
        element={
          <ProtectedRoute>
            <Map />
          </ProtectedRoute>
        }
      />

      <Route path="/form-selection" element={<FormSelectionModal />} />

        <Route path="/property-form" element={<PropertyDetailsForm />} />

    </Routes>

  );
}

function App() {
  return (
    <AuthProvider>
      <Router>
        <AppRoutes />
      </Router>
    </AuthProvider>
  );
}

export default App;
